function art(item){if(item.image)return `<img class="cover-art" src="${esc(item.image)}" alt="${esc(item.title)}的本地图片" loading="lazy">`;return `<span class="cover-art" aria-hidden="true">${covers[item.cover]||covers[{tech:'agent',study:'notebook',life:'life',travel:'landscape',book:'book'}[item.category]]||covers.life}</span>`;}
function contentCard(item){return `<article class="content-card"><button class="cover-button" data-action="content-detail" data-id="${item.id}" aria-label="打开${esc(item.title)}">${art(item)}<span class="cover-badge">${icon(item.image?'image':item.url?'link':'book')}${esc(item.platform)}</span>${item.watch?'<span class="cover-duration">稍后看</span>':''}</button><div class="content-card-body"><div class="content-card-category">${B.categories[item.category]||'未分类'}</div><button class="content-title" data-action="content-detail" data-id="${item.id}">${esc(item.title)}</button><p class="content-summary">${esc(item.summary)}</p><div class="content-tags">${item.tags.slice(0,3).map(t=>`<button class="content-tag inline-tag-button" data-action="content-tag" data-value="${esc(t)}"># ${esc(t)}</button>`).join('')}</div><div class="content-card-footer"><span class="content-status"><i></i>${item.status==='sample'?'示例收藏':item.status==='link-only'?'原链接已保存':item.status==='image-only'?'图片已保存':'本地笔记'}</span><div class="content-actions">${item.deleted?`<button data-action="content-restore" data-id="${item.id}" aria-label="恢复${esc(item.title)}">${icon('rotate')}</button>`:`<button data-action="content-watch" data-id="${item.id}" class="${item.watch?'on':''}" aria-label="${item.watch?'移出稍后看':'加入稍后看'}：${esc(item.title)}" aria-pressed="${!!item.watch}">${icon('clock')}</button><button data-action="content-collection" data-id="${item.id}" aria-label="管理${esc(item.title)}的收藏集">${icon('folder')}</button><button data-action="content-detail" data-id="${item.id}" aria-label="阅读${esc(item.title)}">${icon('arrow')}</button>`}</div></div></div></article>`;}
function garden(){return `<svg viewBox="0 0 450 230" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><g fill="none" stroke="#e0d5ee"><ellipse cx="264" cy="116" rx="151" ry="90" transform="rotate(-17 264 116)"/><ellipse cx="264" cy="116" rx="116" ry="67" transform="rotate(-17 264 116)"/></g><rect x="187" y="45" width="133" height="143" rx="12" fill="#bba5d9" transform="rotate(12 253 116)"/><rect x="172" y="40" width="133" height="143" rx="12" fill="#faf6ff" transform="rotate(-9 239 110)"/><path d="m194 73 76-12" stroke="#d8cbe7" stroke-width="4" stroke-linecap="round"/><path d="m197 85 51-8" stroke="#e4daef" stroke-width="3" stroke-linecap="round"/><rect x="200" y="103" width="73" height="47" rx="7" fill="#e9e1f3" transform="rotate(-9 239 126)"/><path d="m211 132 17-21 17 16 12-13 13 16" stroke="#c6b1db" stroke-width="3" fill="none"/><rect x="93" y="108" width="89" height="68" rx="10" fill="#e2e9d8" transform="rotate(-14 138 142)"/><path d="m122 143 11 8 21-26" stroke="#9bac83" stroke-width="4" stroke-linecap="round" stroke-linejoin="round" fill="none"/><rect x="293" y="127" width="98" height="50" rx="10" fill="#f5e9d3" transform="rotate(10 340 152)"/><text x="309" y="157" fill="#b8a384" font-size="12" font-family="sans-serif" transform="rotate(10 340 152)">Save the good.</text><path d="m327 53 5 12 13 3-10 9 1 13-11-7-12 5 3-13-8-10 13-1z" fill="#c9b3e3"/><circle cx="134" cy="67" r="5" fill="#d3c1e5"/><circle cx="362" cy="99" r="3" fill="#cdb8df"/><path d="M111 189h24m-12-12v24" stroke="#d5c1e4" stroke-width="2"/></svg>`;}
function contentToolbar(){return `<div class="brain-toolbar"><label class="brain-search">${icon('search')}<input type="search" id="brain-search" aria-label="搜索收藏内容" placeholder="搜索标题、正文、标签，找回你的灵感…" value="${esc(brainQuery)}"><kbd>⌘ K</kbd></label><div class="view-switch" aria-label="显示方式"><button class="${brainLayout==='grid'?'active':''}" data-action="brain-layout" data-value="grid" aria-label="卡片视图" aria-pressed="${brainLayout==='grid'}">${icon('grid')}</button><button class="${brainLayout==='list'?'active':''}" data-action="brain-layout" data-value="list" aria-label="列表视图" aria-pressed="${brainLayout==='list'}">${icon('list')}</button></div></div>`;}
function categoryChips(){const active=state.brain.items.filter(x=>!x.deleted);return `<div class="brain-categories" aria-label="内容分类">${Object.entries(B.categories).map(([v,t])=>`<button class="brain-filter ${brainCategory===v?'active':''}" data-action="brain-category" data-value="${v}" aria-pressed="${brainCategory===v}">${icon({all:'grid',tech:'spark',study:'flask',life:'sun',travel:'pin',book:'book'}[v])}${t}${v==='all'?`<small>${active.length}</small>`:''}</button>`).join('')}</div>`;}
function selectedContents(){const items=B.search(state.brain.items,{query:brainQuery,category:brainCategory,collection:page==='library'?selectedCollection:null,watch:page==='watch',trash:showTrash});return items.sort((a,b)=>brainSort==='title'?a.title.localeCompare(b.title,'zh-CN'):new Date(b.createdAt)-new Date(a.createdAt));}
function contentResults(){const result=selectedContents();return `<div class="content-section-heading"><h2>${showTrash?'最近删除':selectedCollection?esc(state.brain.collections.find(c=>c.id===selectedCollection)?.name||'收藏集'):brainQuery?'搜索结果':page==='watch'?'留给下一次的好内容':'最近收藏'} <span class="shelf-count">${result.length}</span></h2><select id="brain-sort" aria-label="收藏排序"><option value="new" ${brainSort==='new'?'selected':''}>最近保存</option><option value="title" ${brainSort==='title'?'selected':''}>按标题排序</option></select></div>${result.length?`<div class="content-grid ${brainLayout==='list'?'grid-list':''}">${result.map(contentCard).join('')}</div>`:`<div class="empty">${icon(showTrash?'trash':'book')}<p>${showTrash?'没有已删除的收藏':brainQuery?'没有找到匹配内容，换个关键词试试。':'这里还空着，保存一点你想留住的内容吧。'}</p>${showTrash?'':button('capture',icon('plus')+'添加收藏','primary small')}</div>`}`;}
todayView=function(){showTrash=false;return header('YOUR SECOND BRAIN','好内容，值得被记住。','收藏灵感，整理知识。让每一次遇见，都能在需要时找回来。',button('capture',icon('plus')+'添加收藏','primary'))+`<section class="brain-hero"><div class="brain-hero-copy"><div class="eyebrow">SAVE ANYTHING. FIND YOUR NEXT IDEA.</div><h2>你的灵感，<br>在这里慢慢生长。</h2><p>文章、视频链接、笔记与截图，<br>收进一个属于你的知识空间。</p><span class="hero-tag">${icon('spark')} 少一点遗忘，多一点连接</span></div><div class="brain-garden">${garden()}</div></section>${contentToolbar()}${categoryChips()}${actionable().length&&!brainQuery?`<button class="mini-opportunity" data-action="navigate" data-page="opportunities"><span>${icon('radar')}</span><span><strong>校园机会雷达 · ${actionable().length} 条待关注</strong><small>志愿招募、科研与讲座，与你的收藏一起留在这里。</small></span>${icon('arrow')}</button>`:''}<section id="content-results">${contentResults()}</section>`;};
libraryView=function(){const collection=state.brain.collections.find(c=>c.id===selectedCollection);return header('YOUR COLLECTIONS',showTrash?'最近删除':collection?esc(collection.name):'把喜欢的，放在一起。',showTrash?'移入这里的收藏可以随时恢复。':collection?'围绕一个目标，慢慢积累属于你的资料。':'为你的兴趣建个小空间，整理起来也可以很轻松。',collection?button('rename-collection',icon('edit')+'重命名','',`data-id="${collection.id}"`)+button('remove-collection','移除收藏集','',`data-id="${collection.id}"`):button('new-collection',icon('plus')+'新建收藏集','primary'))+`${!selectedCollection&&!showTrash?`<div class="collection-strip">${state.brain.collections.map(c=>`<button class="collection-tile ${c.color}" data-action="open-collection" data-id="${c.id}">${icon('folder')}<strong>${esc(c.name)}</strong><small>${state.brain.items.filter(x=>!x.deleted&&x.collections.includes(c.id)).length} 条内容</small></button>`).join('')}<button class="collection-tile new" data-action="new-collection">${icon('plus')}<strong>新的小空间</strong><small>按兴趣，或按计划</small></button></div>`:''}${selectedCollection||showTrash?'<button class="return-link" data-action="all-collections">← 返回全部收藏集</button>':''}${contentToolbar()}${categoryChips()}<section id="content-results">${contentResults()}</section>${!showTrash?`<div class="view-description" style="margin-top:22px">${state.items.filter(x=>x.saved).length} 条校园机会、${state.savedDigests.length} 条精选仍保存在 <button class="btn text" data-action="legacy-saved">校园收藏 →</button><button class="btn text" data-action="show-trash" style="float:right">最近删除</button></div>`:''}`;};
function watchView(){showTrash=false;return header('WATCH LATER','现在收下，慢慢再看。','留给下次的文章、教程和灵感，集中在这里。',button('capture',icon('plus')+'添加收藏','primary'))+`<div class="read-later-top">${icon('clock')}<div><strong>不必现在看完，先记得它。</strong><p>读完后点击时钟标记移出。当前未启用自动推送。</p></div></div>${contentToolbar()}${categoryChips()}<section id="content-results">${contentResults()}</section>`;}
const oldLibraryView=()=>{const items=state.items.filter(x=>x.saved);return header('CAMPUS SAVED','校园里的收获。','保留之前收藏的机会与精选。',button('all-collections','返回收藏集'))+`<div class="full-grid">${items.map(card).join('')}</div><div class="digest-list" style="margin-top:18px">${digests.filter(d=>state.savedDigests.includes(d.id)).map(digestCard).join('')}</div>${!items.length&&!state.savedDigests.length?empty('还没有收藏校园信息。'):''}`;};
const originalSettings=settingsView;
settingsView=function(){return originalSettings()+`<div class="digest-main"><section class="setting-box"><h3>内容收藏</h3><p class="sub">链接只保存地址；文字使用本地摘录与分类规则；图片保存在本浏览器，尚未接入 OCR。</p><div class="setting-row"><span><p>最近删除</p><small>恢复误删的内容</small></span>${button('show-trash','查看','small')}</div></section></div>`;};
render=function(){ensureBrain();$('#page-label').textContent=navs.find(x=>x[0]===page)?.[2]||'校园收藏';$('#nav').innerHTML=navs.map(([id,i,t])=>`<button class="nav-item ${page===id?'active':''}" data-action="navigate" data-page="${id}" ${page===id?'aria-current="page"':''}>${icon(i)}<span>${t}</span>${id==='watch'?`<span class="nav-count">${state.brain.items.filter(x=>x.watch&&!x.deleted).length}</span>`:id==='opportunities'?`<span class="nav-count">${actionable().length}</span>`:''}</button>`).join('');$('#collection-nav').innerHTML=state.brain.collections.map(c=>`<button class="collection-link ${selectedCollection===c.id&&page==='library'?'active':''}" data-action="open-collection" data-id="${c.id}"><span class="collection-dot ${c.color}"></span>${esc(c.name)}<small>${state.brain.items.filter(x=>!x.deleted&&x.collections.includes(c.id)).length}</small></button>`).join('');$('#bell').innerHTML=icon('bell')+(state.reminders.length?'<i class="badge-dot"></i>':'');$('#main').innerHTML=({today:todayView,library:libraryView,watch:watchView,opportunities:opportunitiesView,digest:digestView,sources:sourcesView,settings:settingsView,'campus-saved':oldLibraryView}[page]||todayView)();if(!$('#floating-capture')){const b=document.createElement('button');b.id='floating-capture';b.className='floating-capture';b.dataset.action='capture';b.setAttribute('aria-label','添加收藏');b.textContent='+';document.body.appendChild(b);}$('#floating-capture').hidden=['settings','sources'].includes(page);};
function refreshResults(){const target=$('#content-results');if(target)target.innerHTML=contentResults();}
function contentDetail(id){const item=state.brain.items.find(x=>x.id===id);if(!item)return;showModal(`<div class="content-detail-cover">${art(item)}</div><div class="content-detail-meta">${icon(item.image?'image':item.url?'link':'book')} ${esc(item.platform)} <span>·</span> ${B.categories[item.category]} <span>·</span> ${item.status==='sample'?'示例收藏':new Date(item.createdAt).toLocaleDateString('zh-CN')}</div><h2 id="modal-title">${esc(item.title)}</h2><p class="modal-description">${esc(item.summary)}</p><div class="content-tags">${item.tags.map(t=>`<span class="content-tag"># ${esc(t)}</span>`).join('')}</div><div class="detail-tabs"><span class="small-label">${item.image?'原始图片已保留':item.text?'正文 / 笔记':'原始链接'}</span></div><div class="content-body-text">${esc(item.text||'当前未抓取原文，可点击原链接阅读，或编辑补充笔记。')}</div>${item.url?`<div class="v2-notice">${icon('link')}<a href="${esc(item.url)}" target="_blank" rel="noopener noreferrer">打开原链接 ↗</a><div style="font-size:9px;overflow-wrap:anywhere;margin-top:4px">${esc(item.url)}</div></div>`:''}<div class="detail-tools">${item.deleted?button('content-restore',icon('rotate')+'恢复收藏','primary',`data-id="${id}"`):button('content-watch',icon('clock')+(item.watch?'移出稍后看':'稍后再看'),'primary',`data-id="${id}"`)+button('content-collection',icon('folder')+'加入收藏集','',`data-id="${id}"`)+button('content-edit',icon('edit')+'编辑','',`data-id="${id}"`)+button('content-trash',icon('trash')+'移到最近删除','',`data-id="${id}"`)}</div><p class="field-hint" style="margin-top:13px">${item.status==='sample'?'预置示例；封面为原创示意插画，不代表真实视频或文章缩略图。':item.status==='local'?'摘要来自用户填写或正文摘录，分类由本地关键词规则生成。':'未接入自动正文抓取、视频分析或 OCR。'}</p>`);}
function rememberDraft(){const form=$('#capture-form');if(form)captureDraft=Object.fromEntries(new FormData(form).entries());}
function capture(mode='link',id=null,keep=false){if(!keep){captureDraft={};captureImage=null;editingContent=id;const item=state.brain.items.find(x=>x.id===id);if(item){captureDraft={title:item.title,url:item.url||'',text:item.text||'',summary:item.summary,tags:item.tags.join('、'),category:item.category,watch:item.watch?'on':''};captureImage=item.image;mode=item.image?'image':item.url?'link':'text';}}captureMode=mode;showModal(`<span class="eyebrow">KEEP SOMETHING GOOD</span><h2 id="modal-title">${editingContent?'重新整理这条收藏。':'把这一刻的灵感，收进来。'}</h2><p class="modal-description">${editingContent?'标题、摘要、分类与标签都由你决定。':'保存链接、写一点笔记，或者收下一张图片。'}</p><div class="form-tabs">${[['link','link','链接'],['text','edit','笔记'],['image','image','图片']].map(([v,i,t])=>`<button class="${mode===v?'active':''}" data-action="capture-tab" data-value="${v}">${icon(i)} ${t}</button>`).join('')}</div><form id="capture-form" class="capture-form"><label class="field">标题<input name="title" maxlength="100" required value="${esc(captureDraft.title||'')}" placeholder="给这份灵感起个名字"></label>${mode==='link'?`<label class="field">原始链接<input name="url" type="url" value="${esc(captureDraft.url||'')}" placeholder="https://…" required></label><p class="field-hint">支持保存微信文章、B 站、小红书等链接；本 Demo 不访问或解析链接正文。</p>`:mode==='image'?`<label class="field">选择图片<input id="capture-image-input" type="file" accept="image/png,image/jpeg,image/webp,image/gif"></label><p class="field-hint">PNG / JPG / WebP / GIF，最大 1.5 MB。只在当前浏览器保存，尚无 OCR。</p><div id="capture-image-preview">${captureImage?`<img class="capture-preview" src="${esc(captureImage)}" alt="待保存图片预览">`:''}</div>`:''}<label class="field">${mode==='text'?'笔记正文':'补充笔记'}<textarea name="text" maxlength="12000" ${mode==='text'?'required':''} placeholder="记下内容，也记下你为什么想留住它。">${esc(captureDraft.text||'')}</textarea></label><label class="field">摘要（可选）<textarea name="summary" maxlength="600" style="min-height:65px" placeholder="留空时从你填写的笔记中截取，不会编造链接内容。">${esc(captureDraft.summary||'')}</textarea></label><div class="field-grid"><label class="field">分类<select name="category"><option value="auto">按关键词归类</option>${Object.entries(B.categories).filter(([v])=>v!=='all').map(([v,t])=>`<option value="${v}" ${captureDraft.category===v?'selected':''}>${t}</option>`).join('')}</select></label><label class="field">标签<input name="tags" maxlength="150" value="${esc(captureDraft.tags||'')}" placeholder="用逗号或顿号分隔"></label></div><label class="inline-check"><input name="watch" type="checkbox" ${captureDraft.watch?'checked':''}>加入稍后看</label><div id="capture-error" class="form-error" role="alert"></div><div class="modal-actions"><button class="btn primary" id="capture-submit" type="submit">${icon('check')}${editingContent?'保存修改':'保存到我的大脑'}</button>${button('close','取消')}</div></form>`);}
function collectionForm(id=null){const c=state.brain.collections.find(c=>c.id===id);showModal(`<span class="eyebrow">A SPACE FOR YOUR IDEAS</span><h2 id="modal-title">${c?'给这个空间换个名字。':'新的兴趣，新的小空间。'}</h2><form id="collection-form" data-id="${id||''}"><label class="field">收藏集名称<input name="name" required maxlength="20" value="${esc(c?.name||'')}" placeholder="例如：毕业设计、想去的地方"></label><label class="field">颜色<select name="color">${[['purple','薰衣草紫'],['peach','暖杏色'],['green','鼠尾草绿'],['blue','雾蓝色']].map(([v,t])=>`<option value="${v}" ${c?.color===v?'selected':''}>${t}</option>`).join('')}</select></label><div class="form-error" id="collection-error" role="alert"></div><div class="modal-actions"><button class="btn primary" type="submit">${c?'保存修改':'创建收藏集'}</button>${button('close','取消')}</div></form>`);}
function manageCollections(id){const item=state.brain.items.find(x=>x.id===id);if(!item)return;showModal(`<span class="eyebrow">ORGANIZE YOUR WAY</span><h2 id="modal-title">这份灵感，放在哪里？</h2><p class="modal-description">${esc(item.title)} · 可以加入多个收藏集。</p><form id="assign-form" data-id="${id}"><div class="collection-checks">${state.brain.collections.map(c=>`<label class="collection-check"><input name="collections" type="checkbox" value="${c.id}" ${item.collections.includes(c.id)?'checked':''}><span class="collection-dot ${c.color}"></span>${esc(c.name)}</label>`).join('')||'<p class="field-hint">还没有收藏集。先去「收藏集」创建一个。</p>'}</div><div class="modal-actions"><button class="btn primary" type="submit">保存归类</button>${button('close','取消')}</div></form>`);}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;if(b.dataset.action==='navigate'){selectedCollection=null;showTrash=false;brainCategory='all';brainQuery='';}},true);
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const {action,id,value}=b.dataset,item=state.brain.items.find(x=>x.id===id);switch(action){case'capture':capture();break;case'capture-tab':rememberDraft();capture(value,editingContent,true);break;case'content-detail':contentDetail(id);break;case'content-edit':capture('link',id);break;case'content-watch':if(item&&commitBrain(()=>{item.watch=!item.watch;item.intent=item.watch?'later':'reference';})){render();if(!$('#modal').hidden)contentDetail(id);toast(item.watch?'已加入稍后看':'已移出稍后看');}break;case'content-collection':manageCollections(id);break;case'content-trash':if(item&&commitBrain(()=>item.deleted=true)){closeModal();render();toast('已移到最近删除，可以在收藏集内恢复');}break;case'content-restore':if(item&&commitBrain(()=>item.deleted=false)){closeModal();render();toast('收藏已恢复');}break;case'brain-category':brainCategory=value;render();break;case'brain-layout':brainLayout=value;render();break;case'content-tag':brainQuery=value;render();break;case'new-collection':collectionForm();break;case'rename-collection':collectionForm(id);break;case'open-collection':page='library';selectedCollection=id;brainQuery='';brainCategory='all';showTrash=false;closeModal();render();window.scrollTo(0,0);break;case'all-collections':page='library';selectedCollection=null;showTrash=false;brainCategory='all';brainQuery='';closeModal();render();break;case'show-trash':page='library';selectedCollection=null;showTrash=true;brainCategory='all';brainQuery='';render();break;case'legacy-saved':page='campus-saved';render();break;case'remove-collection':{const c=state.brain.collections.find(c=>c.id===id);if(c)showModal(`<h2 id="modal-title">移除「${esc(c.name)}」？</h2><p class="modal-description">内容仍保留在「我的大脑」，只移除收藏集及归类关系。</p><div class="modal-actions">${button('confirm-remove-collection','移除收藏集','primary',`data-id="${id}"`)}${button('close','取消')}</div>`);break;}case'confirm-remove-collection':if(commitBrain(()=>{state.brain.collections=state.brain.collections.filter(c=>c.id!==id);state.brain.items.forEach(x=>x.collections=x.collections.filter(c=>c!==id));})){selectedCollection=null;closeModal();render();toast('收藏集已移除，内容仍保留');}break;case'about-v2':showModal(`<span class="eyebrow">SAVE A LITTLE. DISCOVER A LOT.</span><h2 id="modal-title">Sift，你的第二大脑。</h2><p class="modal-description">在校园信息雷达之外，为好文章、视频链接、笔记和图片留一个统一的空间。</p><div class="v2-notice">已实现：本地收藏、内容搜索、分类与标签、自建收藏集、稍后看、编辑与恢复、校园机会演示和数据导出。<br><br>尚未接入：微信 / QQ 真实采集、正文自动抓取、图片 OCR、视频分析、大模型和后台推送。</div><p class="modal-description">默认收藏与简报为示例；封面为原创示意插画。所有操作只保存在当前浏览器。示例通知使用预置日期；新导入的消息按当前时间解析。</p>`);break;}});
document.addEventListener('input',e=>{if(e.target.id==='brain-search'){brainQuery=e.target.value;refreshResults();}});
document.addEventListener('change',e=>{if(e.target.id==='brain-sort'){brainSort=e.target.value;refreshResults();}if(e.target.id==='capture-image-input'){const file=e.target.files[0];if(!file)return;const error=$('#capture-error');if(!/^image\/(png|jpeg|webp|gif)$/.test(file.type)||file.size>1.5*1024*1024){error.textContent='请选择不超过 1.5 MB 的 PNG、JPG、WebP 或 GIF 图片。';e.target.value='';return;}error.textContent='';$('#capture-submit').disabled=true;const reader=new FileReader();reader.onload=()=>{captureImage=reader.result;const preview=$('#capture-image-preview');if(preview)preview.innerHTML=`<img class="capture-preview" src="${esc(captureImage)}" alt="待保存图片预览">`;if($('#capture-submit'))$('#capture-submit').disabled=false;};reader.onerror=()=>{if($('#capture-error'))$('#capture-error').textContent='图片读取失败，请重试。';if($('#capture-submit'))$('#capture-submit').disabled=false;};reader.readAsDataURL(file);}});
document.addEventListener('submit',e=>{if(e.target.id==='capture-form'){e.preventDefault();const fd=new FormData(e.target),parsed=B.validate({title:fd.get('title'),url:captureMode==='link'?fd.get('url'):'',text:fd.get('text'),summary:fd.get('summary'),category:fd.get('category'),tags:fd.get('tags'),image:captureMode==='image'?captureImage:null});if(parsed.error){$('#capture-error').textContent=parsed.error;return;}const duplicate=parsed.value.url&&state.brain.items.find(x=>x.id!==editingContent&&!x.deleted&&x.url===parsed.value.url);if(duplicate){$('#capture-error').textContent='这个链接已经收藏过了，可通过搜索找到并编辑。';return;}const item={...parsed.value,watch:fd.has('watch'),intent:fd.has('watch')?'later':'reference'};let id=editingContent||crypto.randomUUID();if(commitBrain(()=>{if(editingContent){const old=state.brain.items.find(x=>x.id===editingContent);Object.assign(old,item);}else state.brain.items.unshift({...item,id,collections:selectedCollection?[selectedCollection]:[],createdAt:new Date().toISOString(),deleted:false,saved:true});})){closeModal();brainQuery='';brainCategory='all';showTrash=false;page='library';render();toast(editingContent?'修改已保存':'已保存到你的第二大脑');}}
if(e.target.id==='collection-form'){e.preventDefault();const fd=new FormData(e.target),name=String(fd.get('name')).trim(),id=e.target.dataset.id;if(!name){$('#collection-error').textContent='请输入名称。';return;}if(state.brain.collections.some(c=>c.name===name&&c.id!==id)){$('#collection-error').textContent='这个名称已存在，换一个试试。';return;}if(commitBrain(()=>{if(id)Object.assign(state.brain.collections.find(c=>c.id===id),{name,color:fd.get('color')});else state.brain.collections.push({id:crypto.randomUUID(),name,color:fd.get('color')});})){closeModal();page='library';render();toast(id?'收藏集已更新':'新的收藏集已创建');}}
if(e.target.id==='assign-form'){e.preventDefault();const id=e.target.dataset.id,fd=new FormData(e.target);if(commitBrain(()=>state.brain.items.find(x=>x.id===id).collections=fd.getAll('collections'))){closeModal();render();toast('收藏集归类已保存');}}});
document.addEventListener('keydown',e=>{const typing=/^(INPUT|TEXTAREA|SELECT)$/.test(document.activeElement?.tagName);if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if($('#modal').hidden){if(!$('#brain-search')){page='library';render();}$('#brain-search')?.focus();}}if(!typing&&!e.metaKey&&!e.ctrlKey&&e.key.toLowerCase()==='n'&&$('#modal').hidden){e.preventDefault();capture();}});
try{localStorage.setItem('zhiyu-demo-v1',JSON.stringify(state));}catch{}
render();
